fn frame(t: i32) {
    host::display::clear(0x0e1014);
    if host::display::state_get(0) == 0 {
        let h: i32 = host::http::get("https://example.com/", 20);
        host::display::state_set(1, h);
        if h < 0 {
            host::display::state_set(0, 3);
        } else {
            host::display::state_set(0, 1);
        }
    }
    if host::display::state_get(0) == 1 {
        let h2: i32 = host::display::state_get(1);
        let r: i32 = host::http::ready(h2);
        if r == 1 {
            host::display::state_set(0, 2);
        } else if r < 0 {
            host::display::state_set(0, 3);
        }
    }
    let phase: i32 = host::display::state_get(0);
    host::display::draw_string(96, 60, "FETCH DASHBOARD", 0xffffff, 2);
    let mut bar: i32 = 0xaa7700;
    if phase == 2 {
        bar = 0x22bb44;
    } else if phase == 3 {
        bar = 0xbb2222;
    }
    host::display::fill_rect(0, 0, 512, 8, bar);
    if phase == 1 {
        host::display::draw_string(96, 200, "REQUEST IN FLIGHT", 0xaa7700, 2);
        if (t / 20) % 2 == 0 {
            host::display::fill_rect(320, 198, 14, 14, 0xaa7700);
        }
    } else if phase == 2 {
        let h3: i32 = host::display::state_get(1);
        host::display::draw_string(96, 160, "UPSTREAM STATUS", 0x888888, 1);
        host::display::draw_number(96, 180, host::http::status(h3), 0x66ddff, 4);
        host::display::draw_string(96, 280, "BODY BYTES", 0x888888, 1);
        host::display::draw_number(96, 300, host::http::body_len(h3), 0xffffff, 4);
    } else {
        host::display::draw_string(96, 200, "FETCH FAILED", 0xbb2222, 3);
        host::display::draw_string(96, 250, "BAD URL OR DENIED BY THE PROXY", 0x777777, 1);
    }
    host::display::present();
}
